mapper.select:
SELECT SBEP.ID, SBEP.EMPLOYEE_CODE, SBEP.EMPLOYEE_NAME, SBEP.DEVICE_CODE, case when SBD.AN_DEVICE_NAME is null then SBD.DEVICE_NAME else SBD.AN_DEVICE_NAME end DEVICE_NAME, SBEP.BEGIN_TIME, SBEP.END_TIME,SBEP.SOURCE_TYPE, SBEP.PROCESS_ID, SBEP.BPM_FLOW_ID,SBEP.REMARK, SBEP.CREATE_BY, SBEP.CREATE_TIME,SBEP.UPDATE_TIME,SBEP.DUTY_DEPT_CODE,SBEP.DUTY_DEPT_NAME,SBEP.DUTY_EMP_LOGIN, SBEP.DUTY_EMP_NAME,SBEP.DUTY_EMP_NO,SBD.AN_FACTORY_CODE,SBD.AN_FACTORY_NAME,SBD.AN_BUILDING,SBEP.ROLE_TYPE, case when SBD.SECURITY_LEVEL ='937_gsjm_2' then '是' else '否' end IS_TOP_SECURITY, SEM.org_name_path DEPT_NAME,SEM.org_code_path DEPT_CODE,SBD.device_type FROM safety_build_employee_power SBEP LEFT JOIN safety_build_device sbd ON SBD.DEVICE_CODE = SBEP.DEVICE_CODE LEFT JOIN safety_employee_message SEM ON SEM.EMP_NO = SBEP.EMPLOYEE_CODE WHERE 1 = 1 and SBEP.DELETE_FLAG = 0
order by ${orderByClause}
limit ${offset}, ${limit}
limit ${limit}

sql.if:
and (

  SEM.org_code_path like CONCAT(#{item},'%')


  or SBEP.EMPLOYEE_CODE = #{createEmployeeNo}


  or SBEP.DEVICE_CODE in

    #{item}


)

mapper.select:
select

  distinct


from (select sbep.ID, sbep.EMPLOYEE_CODE, sbep.EMPLOYEE_NAME, sbep.DEVICE_CODE, ifnull(sbd.AN_DEVICE_NAME,sbd.DEVICE_NAME) DEVICE_NAME,
             sbep.BEGIN_TIME, sbep.END_TIME,sbep.SOURCE_TYPE, sbep.PROCESS_ID, sbep.BPM_FLOW_ID,sbep.REMARK, sbep.CREATE_BY,
             sbep.CREATE_TIME, sbep.UPDATE_TIME, sbep.DUTY_DEPT_CODE,sbep.DUTY_DEPT_NAME,sbep.DUTY_EMP_LOGIN,sbep.DUTY_EMP_NAME,sbep.DUTY_EMP_NO
             ,sbep.DELETE_FLAG,sbd.device_type, sbep.DEPART_CHANGE_TIME
from safety_build_employee_power sbep
       left join safety_build_device sbd on sbep.DEVICE_CODE = sbd.DEVICE_CODE
      where 1 = 1 and sbep.DELETE_FLAG=0 and sbd.REMOVE_FLAG=0 and sbd.DEVICE_STATUS = 1) cur_table




  order by ${orderByClause}



    limit ${offset}, ${limit}


    limit ${limit}

select sem.emp_no ,sem.emp_name ,sem.phone_no ,sem.user_type ,sem.position_code , sem.org_code ,sem.org_name ,sem.org_code_path,sem.org_name_path from safety.safety_employee_message sem where sem.status = 'NORMAL' and sem.emp_no in (select distinct employee_code from safety.safety_build_employee_power sbep where sbep.DELETE_FLAG = 0
and sbep.DUTY_DEPT_CODE is null
)
and sem.emp_no in
#{item}
and sem.org_code is not null

SELECT sbep.EMPLOYEE_CODE,GROUP_CONCAT(sbep.DEVICE_CODE) DEVICE_CODE,GROUP_CONCAT(sbd.AN_DEVICE_NAME) DEVICE_NAME from safety_build_employee_power sbep left join safety_build_device sbd on sbep.DEVICE_CODE = sbd.DEVICE_CODE and sbd.DEVICE_STATUS =1 and sbd.REMOVE_FLAG = 0 and sbd.IS_DELETE = 0 where DELETE_FLAG = 0
and EMPLOYEE_CODE in
#{item}
and sbep.END_TIME >= #{powerTimeEnd}
and sbd.device_type = #{deviceType}
group by EMPLOYEE_CODE

SELECT sbep.EMPLOYEE_CODE, sbep.DEVICE_CODE, sbd.AN_DEVICE_NAME as DEVICE_NAME from safety_build_employee_power sbep left join safety_build_device sbd on sbep.DEVICE_CODE = sbd.DEVICE_CODE and sbd.DEVICE_STATUS =1 and sbd.REMOVE_FLAG = 0 and sbd.IS_DELETE = 0 where DELETE_FLAG = 0
and EMPLOYEE_CODE in
#{item}
and sbep.END_TIME >= #{powerTimeEnd}
and sbd.device_type = #{deviceType}

SELECT c.EMPLOYEE_CODE as empNo, GROUP_CONCAT( AN_FACTORY_CODE ) AS factoryId FROM ( SELECT a.EMPLOYEE_CODE, b.AN_FACTORY_CODE FROM ( SELECT DEVICE_CODE, EMPLOYEE_CODE FROM safety_build_employee_power WHERE EMPLOYEE_CODE IN
#{item}
) a LEFT JOIN safety_build_device b ON a.DEVICE_CODE = b.DEVICE_CODE WHERE b.DEVICE_STATUS = 1 AND b.REMOVE_FLAG = 0 AND b.IS_DELETE = 0 GROUP BY a.EMPLOYEE_CODE, b.AN_FACTORY_CODE ) c GROUP BY c.EMPLOYEE_CODE

SELECT P1.ID PARK_ID,P1.employee_code,p1.FACTORY_ID AN_FACTORY_CODE, TMP1.AN_FACTORY_NAME, TMP1.ID,TMP1.DEVICE_CODE,
       TMP1.DEVICE_NAME,TMP1.device_type ,P1.POWER_BEGIN_TIME BEGIN_TIME,P1.POWER_END_TIME END_TIME
  FROM safety_park_employee_power_info P1
LEFT JOIN (select d1.AN_FACTORY_CODE,d1.AN_FACTORY_NAME,b1.id,b1.DEVICE_CODE,
                  d1.AN_DEVICE_NAME DEVICE_NAME,d1.device_type,b1.EMPLOYEE_CODE
             from safety.safety_build_device D1,
                  SAFETY.safety_build_employee_power B1
             where d1.DEVICE_CODE = b1.DEVICE_CODE
               and d1.REMOVE_FLAG = 0 and d1.IS_DELETE = 0
               and b1.DELETE_FLAG = 0

  and B1.employee_code in

    #{item}



  and D1.device_type = #{deviceType}

) TMP1 ON TMP1.EMPLOYEE_CODE = P1.employee_code AND TMP1.AN_FACTORY_CODE = P1.FACTORY_ID
 WHERE P1.IS_DELETE = 0

    and P1.POWER_END_TIME< #{powerEndTimeEnd} 


  and P1.POWER_END_TIME >= #{powerTimeEnd}


  and p1.employee_code in

    #{item}

select s1.EMPLOYEE_CODE as empNo, s2.AN_BUILDING_CODE as buildingCode, s2.IS_PUBLIC as isPublic, GROUP_CONCAT(s1.ID) AS ids, GROUP_CONCAT(s1.DEVICE_CODE) AS deviceCode, GROUP_CONCAT(s1.DEVICE_NAME) AS deviceName from safety_build_employee_power s1 left join safety_build_device s2 on s1.DEVICE_CODE = s2.DEVICE_CODE where s1.DELETE_FLAG = '0' and s1.EMPLOYEE_CODE in
#{item}
group by s1.EMPLOYEE_CODE, s2.AN_BUILDING_CODE, s2.IS_PUBLIC

